/// carries the `ProviderHttpError` `"<code>: …"` head.
void _recordNetRetry(
  int attempt,
  int maxAttempts,
  Duration delay,
  String reason,
) {
  final session = _session;
  if (session == null) return;
  final statusHead = RegExp(r'^(\d{3}): ').firstMatch(reason);
  final status = statusHead == null
      ? null
